import{_ as t,c as a,o,ah as p,ao as s,ap as i}from"./chunks/framework.Dq2_gudl.js";const m=JSON.parse('{"title":"آیا دوباره او را خواهم دید؟ کتاب مقدس درباره حیوانات و بهشت چه می‌گوید","description":"عمیق‌ترین پرسش پس از از دست دادن حیوان خانگی: آیا او در بهشت خواهد بود؟ رومیان، اشعیا و مکاشفه چه امیدی به ما می‌دهند.","frontmatter":{"title":"آیا دوباره او را خواهم دید؟ کتاب مقدس درباره حیوانات و بهشت چه می‌گوید","description":"عمیق‌ترین پرسش پس از از دست دادن حیوان خانگی: آیا او در بهشت خواهد بود؟ رومیان، اشعیا و مکاشفه چه امیدی به ما می‌دهند."},"headers":[],"relativePath":"fa/pets-in-heaven/will-i-see-my-pet-again.md","filePath":"fa/pets-in-heaven/will-i-see-my-pet-again.md"}'),l={name:"fa/pets-in-heaven/will-i-see-my-pet-again.md"};function n(r,e,h,c,d,f){return o(),a("div",null,[...e[0]||(e[0]=[p('<div class="pl-quote"><p>«می‌دانم که خودم در بهشت خواهم بود. فقط می‌خواهم بدانم — آیا او هم آنجا منتظر من است؟»</p><p class="pl-quote-soft">این پرسشی است که داغداران همراهان حیوان بیشتر از همه می‌پرسند و سخت‌تر از همه به زبان می‌آورند.</p></div><section class="pl-section"><h2>نخست یک سخن صادقانه</h2><p>کتاب مقدس هیچ آیه‌ای ندارد که بگوید «هر حیوان خانگی در بهشت با صاحبش دیدار خواهد کرد». هر کس این را با چنین اطمینانی بگوید، فراتر از آنچه کتاب مقدس می‌گوید رفته است.</p><p>اما به همین دلیل ناامید نشوید. تصویری که کتاب مقدس می‌کشد بسیار وسیع‌تر از آن است که گمان می‌کنیم: رستگاری خدا هرگز فقط «بیرون کشیدن چند روح انسانی از میان ویرانه‌ها» نبود — بلکه <strong>نوزایی تمام آفرینش</strong> است. و حیوانات از آغاز تا پایان در آن تصویر هستند.</p></section><section class="pl-section"><h2>۱. خود آفرینش همراه ما انتظار می‌کشد</h2><blockquote><p><strong>رومیان ۸:۱۹-۲۲</strong></p><p>&quot;For the earnest expectation of the creature waiteth for the manifestation of the sons of God… For we know that the whole creation groaneth and travaileth in pain together until now.&quot;</p></blockquote><p>پولس در اینجا چیزی شگفت‌انگیز می‌گوید: تنها انسان‌ها نیستند که آه می‌کشند و انتظار می‌کشند. <em>خود آفرینش</em> نیز آه می‌کشد و در انتظار رستگاری است. حیوانات صحنه‌ای رهاشده بیرون از نجات نیستند — آن‌ها به همان پایانی می‌نگرند که ما.</p><p>وقتی می‌گویید «او این‌قدر مهربان بود، نباید فقط ناپدید شود»، آنچه حس می‌کنید همانی است که آفرینش حس می‌کند. کتاب مقدس می‌گوید آن درد پاسخ خواهد گرفت.</p></section><section class="pl-section"><h2>۲. جهانی که خدا خواهد ساخت، حیوان دارد</h2><blockquote><p><strong>اشعیا ۱۱:۶-۹</strong></p><p>&quot;The wolf also shall dwell with the lamb, and the leopard shall lie down with the kid; and the calf and the young lion and the fatling together; and a little child shall lead them.&quot;</p></blockquote><p>آینده‌ای که اشعیا دید جهانی از نور و ابر تنها نبود. او گرگ، بره، پلنگ، بزغاله، گوساله و شیر دید — جهانی که در آن هیچ‌کس آسیب نمی‌زند و همه در امنیت می‌خوابند.</p><p>اگر مقصود خدا از حیوانات این بود که «آن‌ها فقط برای این زندگی‌اند و بعد تمام»، جایی برایشان در وعده‌هایش نمی‌گذاشت. گذاشت.</p><p>و مکاشفه در توصیف آسمان و زمین نو می‌گوید:</p><blockquote><p><strong>مکاشفه ۲۱:۴-۵</strong></p><p>&quot;And God shall wipe away all tears from their eyes; and there shall be no more death, neither sorrow, nor crying, neither shall there be any more pain: for the former things are passed away. …Behold, I make all things new.&quot;</p></blockquote><p>«مرگ دیگر نخواهد بود» اعلامی است درباره تمام آفرینش. مرگی که حیوان شما از آن گذشت یکی از چیزهایی است که از میان خواهد رفت.</p></section><section class="pl-section"><h2>۳. پس تا چه حد می‌توانیم امید داشته باشیم؟</h2><p>می‌توانیم امید داشته باشیم، چون خدا آنچه را ساخته رها نمی‌کند. می‌توانیم امید داشته باشیم، چون رستاخیز مسیح نخستین میوه آفرینش نو است و کتاب مقدس می‌گوید دامنه آن «همه چیز» است. می‌توانیم امید داشته باشیم، چون خدایی که حیوانات را آفرید و از آن‌ها خوشنود بود، ناگهان از آن‌ها غافل نمی‌شود.</p><p>اما «آیا همان خواهد بود؟» و «آیا مرا به یاد می‌آورد؟» — کتاب مقدس جزئیات نمی‌دهد. خدایی قابل‌اعتماد به ما می‌دهد و جزئیات در دست اوست. این سکوت برای آزار ما نیست؛ دعوتی است به سپردن آنچه نمی‌دانیم به دست‌های مهربان.</p><p class="pl-quote-soft">اگر بخواهید، می‌توانید این‌گونه دعا کنید:</p></section><div class="pl-quote"><p>«خداوندا، جزئیات بهشت را نمی‌دانم، اما باور دارم که تو مهربانی.<br>تو او را آفریدی. تو هر روز زندگی‌اش را نگه داشتی. تو الان اشک‌هایم را می‌بینی.<br>او را به دستان تو می‌سپارم — همان‌گونه که خودم را می‌سپارم.<br>اگر در وعده‌های تو جایی برای او هست، سپاسگزارم.<br>و اگر کسی باید اکنون از او مراقبت کند، خوشحالم که تو هستی. آمین.»</p></div><section class="pl-section"><h2>برای روزی که بسیار سخت است</h2><p>مزمورنویس نوشت: «خداوندا، انسان و حیوان را نگه می‌داری» (مزامیر ۳۶:۶). جمله‌ای کوتاه است، اما یکی از آیات کم‌یابی است که حیوانات را مستقیم در مراقبت نگه‌دارنده خدا قرار می‌دهد.</p><p>حیوان شما از آن خدایی است که «انسان و حیوان را نگه می‌دارد». شاید آنچه امروز لازم دارید پاسخی کامل نباشد، بلکه فقط این باشد: او در دستان خداست و خدا مهربان است.</p><p><a href="/fa/pets-in-heaven/">← بازگشت به Pets in Heaven</a> ｜ بعدی: <a href="/fa/pets-in-heaven/not-one-sparrow-forgotten">حتی یک گنجشک فراموش نمی‌شود</a></p></section><div class="pl-cta"><h2>نام او را بنویسید.</h2><p>نامش، جای مورد علاقه‌اش، جمله‌ای که هرگز نگفتید. PetLoss فضایی خصوصی است — بدون بارگذاری، بدون فشار — که کمک می‌کند آهسته مرتب کنید.</p><a class="pl-download" href="https://apps.apple.com/us/app/petloss-memorial-healing/id6757967412">دانلود از App Store</a></div><div class="pl-bible"><h3>بگذارید کلام خدا همراهتان بماند</h3><p>همهٔ آیات این نوشته از کتاب مقدس است. با اپلیکیشن Rainbow Bible می‌توانید هر زمان کتاب مقدس را بخوانید و ویجت «آیهٔ روز» را تنظیم کنید — نوری کوچک برای روزهایی که دلتان تنگ است.</p><div class="pl-bible-shots"><figure><img src="'+s+'" alt="ابزارک Rainbow Bible، آیهٔ ۲ تیموتائوس ۲:۱۳" loading="lazy"><figcaption>آیهٔ روز روی صفحهٔ اصلی</figcaption></figure><figure><img src="'+i+'" alt="اپ Rainbow Bible — موضوع حیوانات خانگی در بهشت، متی ۱۰:۲۹-۳۱" loading="lazy"><figcaption>در موضوع «حیوانات خانگی در بهشت» بخوانید</figcaption></figure></div><a class="pl-bible-download" href="https://apps.apple.com/app/id6756217525">دریافت Rainbow Bible از App Store</a></div>',9)])])}const u=t(l,[["render",n]]);export{m as __pageData,u as default};
